import React, { useState, useEffect, useCallback } from 'react';
import { Wallet, ArrowUpRight, ArrowDownLeft, RefreshCw, AlertCircle, CheckCircle2, CreditCard } from 'lucide-react';
import { meApi } from '../api/me';
import { generateIdempotencyKey, paymentNavigation } from '../api/payments';
import { useShop } from '../context/ShopContext';
import { StoreCreditBalance, StoreCreditTransaction } from '../types';

const StoreCredit: React.FC = () => {
  const { shopConfig, formatPrice } = useShop();
  const [balance, setBalance] = useState<StoreCreditBalance | null>(null);
  const [transactions, setTransactions] = useState<StoreCreditTransaction[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Top-up form
  const [topUpAmount, setTopUpAmount] = useState('');
  const [idempotencyKey, setIdempotencyKey] = useState(() => generateIdempotencyKey());
  const [topUpSubmitting, setTopUpSubmitting] = useState(false);
  const [topUpMessage, setTopUpMessage] = useState<string | null>(null);

  const activeCurrency = balance?.currency || shopConfig.currency || 'IRR';

  const loadCreditData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const [bal, txs] = await Promise.all([
        meApi.getCreditBalance(),
        meApi.getCreditTransactions(),
      ]);
      setBalance(bal);
      setTransactions(txs);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load store credit balance and transactions.');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadCreditData();
  }, [loadCreditData]);

  const handleTopUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setTopUpMessage(null);

    const parsedAmount = Math.round(Number(topUpAmount));
    if (!Number.isInteger(parsedAmount) || parsedAmount <= 0) {
      setError('Enter a valid positive integer top-up amount.');
      return;
    }

    setTopUpSubmitting(true);
    try {
      const res = await meApi.topUpCredit(idempotencyKey, {
        amount: parsedAmount,
        currency: activeCurrency,
        destination: 'store_credit',
      });
      const redirectTarget = res.redirectUrl || res.redirect;
      if (redirectTarget) {
        paymentNavigation.redirectToGateway(redirectTarget);
        return;
      }
      setTopUpMessage(`Top-up ${res.topUpId || ''} initiated.`);
      setTopUpAmount('');
      setIdempotencyKey(generateIdempotencyKey());
      await loadCreditData();
    } catch (err: any) {
      if (err?.status !== 409) {
        setIdempotencyKey(generateIdempotencyKey());
      }
      setError(err?.error || err?.message || 'Failed to initiate store credit top-up.');
    } finally {
      setTopUpSubmitting(false);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-[#E4E4DE] dark:border-[#222630] pb-6">
        <div>
          <span className="text-xs font-mono font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
            Account Ledger
          </span>
          <h1 className="text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight mt-1">
            Store Credit &amp; Top-Ups
          </h1>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
            View available store credit from refunds or direct top-ups in {activeCurrency}.
          </p>
        </div>

        <button
          type="button"
          onClick={loadCreditData}
          disabled={isLoading}
          className="px-4 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-semibold text-slate-700 dark:text-slate-200 hover:border-slate-400 transition-colors inline-flex items-center gap-2 self-start sm:self-auto"
        >
          <RefreshCw size={14} className={isLoading ? 'animate-spin' : ''} />
          <span>Refresh</span>
        </button>
      </div>

      {error && (
        <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
          <AlertCircle size={15} className="shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {topUpMessage && (
        <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs text-emerald-700 dark:text-emerald-300 flex items-center gap-2">
          <CheckCircle2 size={15} className="shrink-0" />
          <span>{topUpMessage}</span>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Balance Overview Card */}
        <div className="lg:col-span-5 bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-2xl p-6 space-y-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
              <Wallet size={20} />
            </div>
            <div>
              <div className="text-xs font-medium text-slate-500 dark:text-slate-400">
                Available Balance
              </div>
              <div className="text-2xl font-extrabold font-mono tabular-nums text-slate-900 dark:text-white">
                {isLoading ? '—' : formatPrice(balance?.availableBalance ?? balance?.balance ?? 0, activeCurrency)}
              </div>
            </div>
          </div>

          {balance?.holdAmount !== undefined && balance.holdAmount > 0 && (
            <div className="pt-3 border-t border-[#E4E4DE] dark:border-[#222630] flex items-center justify-between text-xs">
              <span className="text-slate-500 dark:text-slate-400">Pending Hold</span>
              <span className="font-mono tabular-nums font-semibold text-amber-600 dark:text-amber-400">
                {formatPrice(balance.holdAmount, activeCurrency)}
              </span>
            </div>
          )}

          {/* Top-Up Form */}
          <form onSubmit={handleTopUp} className="pt-4 border-t border-[#E4E4DE] dark:border-[#222630] space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">
                <CreditCard size={15} className="text-emerald-600 dark:text-emerald-400" />
                <span>Add Store Credit</span>
              </h2>
              <span className="text-[11px] font-mono text-slate-500">{activeCurrency}</span>
            </div>

            <div>
              <label htmlFor="credit-topup-amount" className="block text-xs font-medium text-slate-600 dark:text-slate-400 mb-1.5">
                Amount ({activeCurrency})
              </label>
              <input
                id="credit-topup-amount"
                type="number"
                min={1}
                step={1}
                required
                value={topUpAmount}
                onChange={e => setTopUpAmount(e.target.value)}
                placeholder={`Enter positive integer (${activeCurrency})`}
                className="w-full px-3.5 py-2.5 rounded-lg bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] text-sm font-mono tabular-nums text-slate-900 dark:text-white focus:outline-none focus:border-emerald-600"
              />
            </div>

            <button
              type="submit"
              disabled={topUpSubmitting}
              className="w-full py-2.5 px-4 rounded-lg bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white text-xs font-bold transition-colors"
            >
              {topUpSubmitting ? 'Initiating Top-Up...' : 'Top Up Store Credit'}
            </button>
          </form>
        </div>

        {/* Transaction Ledger */}
        <div className="lg:col-span-7 bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-2xl overflow-hidden">
          <div className="px-6 py-4 border-b border-[#E4E4DE] dark:border-[#222630] flex items-center justify-between">
            <h2 className="text-sm font-bold text-slate-900 dark:text-white">
              Credit Transactions
            </h2>
            <span className="text-xs font-mono tabular-nums text-slate-500">
              {transactions.length} entries
            </span>
          </div>

          {isLoading ? (
            <div className="p-8 text-center text-xs text-slate-500">Loading credit ledger...</div>
          ) : transactions.length === 0 ? (
            <div className="p-10 text-center text-xs text-slate-500 dark:text-slate-400">
              No store credit transactions recorded yet.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="border-b border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#161922] text-[11px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                    <th className="py-3 px-4">Type</th>
                    <th className="py-3 px-4">Details</th>
                    <th className="py-3 px-4 text-right">Amount</th>
                    <th className="py-3 px-4 text-right">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E4E4DE] dark:divide-[#222630] text-xs">
                  {transactions.map((tx, idx) => {
                    const isCredit =
                      tx.direction === 'credit' ||
                      tx.amount >= 0 ||
                      /credit|refund|topup|top_up/i.test(tx.type || '');
                    return (
                      <tr key={tx.transactionId || tx._id || tx.id || idx} className="hover:bg-slate-50/70 dark:hover:bg-[#171A21]">
                        <td className="py-3 px-4 font-mono font-semibold text-slate-800 dark:text-slate-200 whitespace-nowrap">
                          <span className="inline-flex items-center gap-1.5">
                            {isCredit ? (
                              <ArrowDownLeft size={13} className="text-emerald-600 dark:text-emerald-400" />
                            ) : (
                              <ArrowUpRight size={13} className="text-rose-500" />
                            )}
                            <span>{tx.type || 'CREDIT'}</span>
                          </span>
                        </td>
                        <td className="py-3 px-4 text-slate-600 dark:text-slate-400">
                          <div>{tx.description || tx.reason || 'Store credit entry'}</div>
                          {(tx.orderId || tx.refundId || tx.topUpId) && (
                            <div className="text-[11px] font-mono text-slate-400 mt-0.5">
                              {[tx.orderId && `Order: ${tx.orderId}`, tx.refundId && `Refund: ${tx.refundId}`, tx.topUpId && `TopUp: ${tx.topUpId}`]
                                .filter(Boolean)
                                .join(' · ')}
                            </div>
                          )}
                        </td>
                        <td
                          className={`py-3 px-4 text-right font-mono tabular-nums font-bold whitespace-nowrap ${
                            isCredit ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'
                          }`}
                        >
                          {isCredit && tx.amount > 0 ? '+' : ''}
                          {formatPrice(Math.abs(Number(tx.amount) || 0), tx.currency || activeCurrency)}
                        </td>
                        <td className="py-3 px-4 text-right text-slate-500 whitespace-nowrap font-mono tabular-nums">
                          {tx.createdAt ? new Date(tx.createdAt).toLocaleDateString() : '—'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default StoreCredit;
